#![cfg(not(target_arch="wasm32"))]
use semio_framework_job::*;use semio_framework_job_worker::{WorkerJobOutcome,WorkerJobPoll,WorkerJobSession,WorkerJobSessionAdmission,OriginalWorkerFixtureCaller};use semio_framework_job_worker_authority::{BatchDriveConfig,BatchJobParams};
use semio_ui_wgpu_hosting::host::{ClipboardIoJob,ClipboardIoOperation};
fn clock()->Option<u64>{Some(1000)}
fn stock()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:100_000,maximum_copy_bytes:1<<24,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:128}}
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap()}
fn policy(law:&serde_json::Value,key:&str)->RetainedCloneGrant{let value=&law[key];RetainedCloneGrant{maximum_items:value["items"].as_u64().unwrap()as usize,maximum_copy_bytes:value["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:value["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:value["release"].as_u64().unwrap()as usize,maximum_depth:value["depth"].as_u64().unwrap()as usize}}
fn params(caller:&mut OriginalJobFixtureCaller,grant:RetainedCloneGrant)->Option<BatchJobParams>{Some(BatchJobParams{operation:OperationId(71),generation:Generation(3),cancel:caller.admit_alias(grant),config:BatchDriveConfig{retained:grant,site:"original_clipboard_fixture",stage:InteractiveStage::InteractiveStep,fuel_per_step:64,step_budget_us:500},now_us:clock})}
fn written(job:&ClipboardIoJob)->&String{let Some(ClipboardIoOperation::Write(text))=job.operation.as_ref()else{panic!("write operation retained")};text}
fn admit(caller:&mut OriginalJobFixtureCaller,admission:&mut WorkerJobSessionAdmission<ClipboardIoJob,WorkerJobSession<ClipboardIoJob>>,job:&mut Option<ClipboardIoJob>,params:&mut Option<BatchJobParams>)->Option<WorkerJobSession<ClipboardIoJob>>{
 let mut output=None;for _ in 0..4096{if output.is_some()||caller.turn(stock(),|cx|admission.advance(job,params,&mut output,cx)).unwrap(){break}}
 assert!(admission.terminal_is_empty()&&job.is_none()&&params.is_none());output
}
fn prepare(caller:&mut OriginalJobFixtureCaller,grant:RetainedCloneGrant,job:ClipboardIoJob)->WorkerJobSession<ClipboardIoJob>{let mut job=Some(job);let mut params=params(caller,grant);admit(caller,&mut WorkerJobSessionAdmission::new(),&mut job,&mut params).expect("authentic original policy funds session admission")}
fn acknowledge(caller:&mut OriginalJobFixtureCaller,outcome:&mut WorkerJobOutcome<ClipboardIoJob>){for _ in 0..4096{if outcome.outcome_descriptor().is_none(){return}caller.turn(stock(),|cx|outcome.acknowledge_outcome(cx)).unwrap();}assert!(outcome.outcome_descriptor().is_none())}
fn close(caller:&mut OriginalJobFixtureCaller,grant:RetainedCloneGrant,session:&mut WorkerJobSession<ClipboardIoJob>){for _ in 0..4096{if session.terminal_is_empty(){return}let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.close_owner(grant,session).unwrap());assert_eq!(step.progress(),caller.receipt());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}panic!("original session closure must finish: phase={:?} demand={:?}",session.close_phase(),session.retirement_demands(grant.maximum_copy_bytes))}
#[test]
fn original_clipboard_admission_denial_preserves_text_and_cancelled_write_never_enters_its_producer(){
 let law=fixture();let grant=policy(&law,"policy");let mut caller=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),stock(),clock,10_000_000,1_000_000);let expected:String=serde_json::from_value(law["text"].clone()).unwrap();let mut text=String::with_capacity(law["capacity"].as_u64().unwrap()as usize);text.push_str(&expected);let pointer=text.as_ptr();let capacity=text.capacity();let mut job=Some(ClipboardIoJob::write(text));
 let demand=WorkerJobSession::<ClipboardIoJob>::admission_demand();assert!(demand.capacity_bytes>0&&demand.capacity_bytes<=stock().maximum_capacity_bytes);let mut params=params(&mut caller,grant);let mut admission=WorkerJobSessionAdmission::new();let mut output=None;
 let(advanced,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(RetainedCloneGrant{maximum_items:0,..grant},|cx|admission.advance(&mut job,&mut params,&mut output,cx)).unwrap());assert!(!advanced&&output.is_none()&&params.is_some());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(written(job.as_ref().unwrap()).as_ptr(),pointer);assert_eq!(written(job.as_ref().unwrap()).capacity(),capacity);
 let mut session=admit(&mut caller,&mut admission,&mut job,&mut params).expect("authentic original policy funds session admission");caller.cancel().cancel_now();
 let(stepped,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(stock(),|cx|session.try_step_on_original_caller(cx)).unwrap());let(ticket,kind)=stepped.expect("cancelled caller still receives its idle session turn");assert_eq!(kind,WorkerJobPoll::Outcome);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(session.take_retained_step_receipt().unwrap().unwrap().1,RetainedCloneProgress::default());
 let outcome=session.take_outcome(ticket).unwrap();assert!(outcome.outcome_descriptor().is_none()&&outcome.outcome().unwrap().is_none());assert_eq!(written(outcome.job()).as_ptr(),pointer);assert_eq!(written(outcome.job()).capacity(),capacity);
 outcome.begin_close();close(&mut caller,policy(&law,"close"),&mut session);drop(session);caller.retire(grant);
}
#[test]
fn original_clipboard_read_fault_borrows_before_ack_and_paid_terminal_close(){
 let law=fixture();let grant=policy(&law,"policy");let expected:String=serde_json::from_value(law["expectedDiagnostic"].clone()).unwrap();let mut caller=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),stock(),clock,10_000_000,1_000_000);let mut session=prepare(&mut caller,grant,ClipboardIoJob::read());
 for _ in 0..4096{let Some((ticket,kind))=caller.turn(stock(),|cx|session.try_step_on_original_caller(cx)).unwrap()else{continue};let(_,receipt)=session.take_retained_step_receipt().unwrap().unwrap();assert!(receipt.fits(stock()));let mut outcome=if kind==WorkerJobPoll::Terminal{session.take_terminal().unwrap()}else{session.take_outcome(ticket).unwrap()};if kind==WorkerJobPoll::Terminal{let(view,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||outcome.outcome().unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let Some(JobOutcomeView::Fault{detail,..})=view else{panic!("existing bounded read producer must publish its actual fault")};assert_eq!(detail.page(0).unwrap(),expected.as_bytes());assert!(ClipboardIoJob::read_candidate(&JobOutcomeView::Fault{detail,admission:outcome.outcome_descriptor().unwrap().admission()}).is_none());acknowledge(&mut caller,&mut outcome);outcome.begin_close();close(&mut caller,policy(&law,"close"),&mut session);drop(session);caller.retire(grant);return}
 if outcome.outcome_descriptor().is_some(){acknowledge(&mut caller,&mut outcome)}outcome.resume().ok().unwrap();}
 panic!("bounded original read diagnostic must finish")
}
